import{_ as i,C as t,o as n,c as o,E as a,a2 as l}from"./chunks/framework.BOeh4kYD.js";const h="/joinwell52/assets/current-context-20260916/same-place-new-visit.figure.en.svg",v=JSON.parse('{"title":"Back in the same workspace, but which visit owns the result?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Back in the same workspace, but which visit owns the result?","date":"2026-09-16","published_date":"2026-09-16","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Back in the same workspace, but which visit owns the result?","summary":"You leave workspace A, visit B, and return to A. A request from the first visit finally arrives. A controlled timing experiment asks whether it still belongs on screen.","cover":"/assets/current-context-20260916/same-place-new-visit.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments on pinned source; scope in article","pageClass":"current-context-article"},"headers":[],"relativePath":"en/engineering/2026-09-16-same-place-new-visit.md","filePath":"en/engineering/2026-09-16-same-place-new-visit.md","lastUpdated":1789531953000}'),c={name:"en/engineering/2026-09-16-same-place-new-visit.md"};function d(p,e,u,m,g,w){const r=t("ArticleCover"),s=t("ArticleTableScroll");return n(),o("div",null,[a(r,{image:"/assets/current-context-20260916/same-place-new-visit.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"Back in the same workspace, but which visit owns the result?",summary:"You leave workspace A, visit B, and return to A. A request from the first visit finally arrives. A controlled timing experiment asks whether it still belongs on screen.",version:"2026-09-16",languageHref:"/zh/engineering/2026-09-16-same-place-new-visit",languageLabel:"中文"}),a(s,{language:"en"}),e[0]||(e[0]=l('<h1 id="back-in-the-same-workspace-but-which-visit-owns-the-result" tabindex="-1">Back in the same workspace, but which visit owns the result? <a class="header-anchor" href="#back-in-the-same-workspace-but-which-visit-owns-the-result" aria-label="Permalink to &quot;Back in the same workspace, but which visit owns the result?&quot;">​</a></h1><p>You open workspace A while its file list is loading. You switch to B, then return to A.</p><p>Only now does the first request for A finish. The workspace name is right. It is still a file-list request. <strong>But does the answer belong to this visit or the previous one?</strong></p><p>The name matches again, but the first request has not become a new request. We wanted to test whether the application can distinguish those visits.</p><h2 id="give-each-visit-a-distinguishable-marker" tabindex="-1">Give each visit a distinguishable marker <a class="header-anchor" href="#give-each-visit-a-distinguishable-marker" aria-label="Permalink to &quot;Give each visit a distinguishable marker&quot;">​</a></h2><p>The idea comes from <a href="https://github.com/stablyai/orca/pull/20914" target="_blank" rel="noreferrer">Orca #20914</a>, submitted by Jinwoo-H. Orca&#39;s mobile client requests file information from the computer running an AI assistant, then retains results for later queries.</p><p>This change gives one object responsibility for pending requests and temporarily stored results. Think of it as a record keeper for the current period of use: it needs to know which results still belong and which have become obsolete.</p><p>The implementation attaches a valid-at-the-time marker to a request. A switch or reset retires the old marker. Returning to A does not reactivate the first visit&#39;s marker. The code calls these distinct periods “generations.”</p><p>That interested us because persistent assistants encounter switching, reconnection, and recovery. Recognizing the workspace&#39;s name alone can miss changes it has gone through. Upstream explicitly tests A→B→A; we used that scenario to build a controlled timing experiment.</p><h2 id="make-the-first-result-arrive-late" tabindex="-1">Make the first result arrive late <a class="header-anchor" href="#make-the-first-result-arrive-late" aria-label="Permalink to &quot;Make the first result arrive late&quot;">​</a></h2><p>We executed the complete module at a fixed version: start a request for A, hold its answer back, change the scope, and only then deliver the old result. We checked whether it could be stored and read again.</p><p>For comparison, we removed only the check that asks whether the request&#39;s marker still belongs to the current generation. This deliberately modified version helps explain the mechanism; <strong>it is not a historical Orca release</strong>.</p><table tabindex="0"><thead><tr><th>Constructed scenario</th><th>Original module</th><th>Generation check removed</th></tr></thead><tbody><tr><td>A→B→A; first A result arrives late</td><td>Refuses storage</td><td>Stores old result; later readable</td></tr><tr><td>Same name, explicit reset</td><td>Refuses storage</td><td>Stores old result; later readable</td></tr><tr><td>Tell the owner that the identity epoch changed</td><td>Refuses old request marker</td><td>Stores result, but new scope cannot read it</td></tr><tr><td>Identity changes without informing the owner</td><td><strong>Old result remains storable and readable</strong></td><td>Old result remains storable and readable</td></tr><tr><td>Pass a request marker to another owner</td><td>Refuses: marker belongs elsewhere</td><td>Still refuses</td></tr></tbody></table><p>The first two rows make the central point: rejecting a stale result requires more than the workspace name.</p><p>The fourth row shows that protection also needs an input. If the caller never reports an identity change, the owner cannot know that a new period has begun. We deliberately omitted that signal in a synthetic case; this does not establish a defect in the real login flow.</p><p><img src="'+h+'" alt="Two visits to the same workspace"></p><p><em>Figure 1. The first request for A arrives after the returning visit has begun a new generation. Source: our controlled schedules; diagram by the authors, not a recording of the mobile UI.</em></p><h2 id="stored-read-and-displayed-are-separate-steps" tabindex="-1">Stored, read, and displayed are separate steps <a class="header-anchor" href="#stored-read-and-displayed-are-separate-steps" aria-label="Permalink to &quot;Stored, read, and displayed are separate steps&quot;">​</a></h2><p>Another result was less obvious. We changed the outside scope without yet informing the owner. Submitting the old result then returned “committed.”</p><p>On the next read with the new scope, the owner noticed the change and cleared the previously stored contents. That read did not return the old value.</p><p>These temporarily stored contents are the cache. The implementation checks both when accepting a result and when a later reader supplies a scope. Reading only the “committed” verdict misses the second part of the protection.</p><p>The screen is another step. A caller can still hold an old asynchronous result. If it displays that value directly, without another cache read, it needs its own ordering check. Orca&#39;s file-search code retains such a display check. Our experiment did not run the mobile UI, so it cannot guarantee what every screen shows.</p><p><strong>To understand whether stale content can appear, follow the result: who accepts it, who reads it, and who puts it on screen?</strong></p><h2 id="which-changes-must-the-application-report" tabindex="-1">Which changes must the application report? <a class="header-anchor" href="#which-changes-must-the-application-report" aria-label="Permalink to &quot;Which changes must the application report?&quot;">​</a></h2><p>Workspace selection is an obvious change. Reauthentication or moving execution to another computer can also make earlier results unsuitable.</p><p>The next questions are therefore specific: which events make this data obsolete, where does the application obtain reliable signals of those events, and who supplies them to the request owner? Naming a field “version” does not establish its source.</p><p>Users can contribute concrete observations: after returning to a workspace, did the file list show new content and then briefly revert? Was there a reconnection or account switch? Those details help developers reproduce the right ordering.</p><p>Developers can also consider how many updates one request produces. If it first publishes “loading” and later “ready,” how should a request marker constrain both updates? That is a follow-up design question, not an extension tested in this experiment.</p><p>Returning to the same place does not reverse time. The application still needs to know which visit owns the result.</p><details><summary>For technical readers: additional schedules, boundaries, and pinned version</summary><p>Source author: Jinwoo-H. Candidate: <code>89711d6f55670781d23fc1a2d4e2aecf4d725758</code>; merged on 2026-09-16 UTC. The complete <code>generation-scoped-request-owner.ts</code> was executed. Eight schedules or boundary cases were run against the original and a mutation removing only the generation comparison: 16 observations.</p><p>The request marker described above is the lease; the caller supplies a scope. The implementation checks both lease ownership and generation. Removing the generation comparison preserves the ownership check. An identity epoch included in scope changes the key, so an accepted old value in the ablation does not necessarily become readable under the new scope.</p><p>Additional cases cover normal same-generation publication and stale-request cleanup. When an old request settled while a new one remained pending, cleanup preserved the new in-flight entry; another load shared its promise and started zero duplicate loads.</p><p>Upstream states that mobile lacks an available negotiated capability epoch; the experiment does not invent one. Its authentication-epoch boundary case does not establish a real authentication path. A separate query sequence protects display, and the cache commit verdict is not a freshness guarantee for a value already held by the caller. Upstream identifies loading/ready publication in a future status-loader migration as unfinished work.</p><p>No real RPC, mobile UI, host migration, or login flow was run. The private TypeScript lease brand is not claimed to isolate hostile JavaScript in the same process.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-16-current-context" target="_blank" rel="noreferrer">Pinned source, all observations, and runnable probes</a>. These observations do not establish a corresponding CodeFlowMu defect.</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',31))])}const f=i(c,[["render",d]]);export{v as __pageData,f as default};
